define(['jquery', 'Magento_Customer/js/customer-data'], function($, customerData) {
    'use strict';
    return function() {
        $(document).ready(function() {
            let cartData = customerData.get('cart');
            let prevCount = cartData().summary_count || 0;
            var hashValue = window.location.hash;
            if (hashValue == '#shipping') {
                $('body').addClass('shipping');
                $('#custom-opc-block-summary1').hide();
                $('table.data.table.table-totals').hide();
                $('.sucure-checkout').hide();
            }
            $(document).on('click', '#confirm_shipping', function() {
                if ($('body').hasClass('shipping')) {
                    $('body').removeClass('shipping');
                    $('body').addClass('payment');
                    $('#custom-opc-block-summary1').show();
                    $('table.data.table.table-totals').show();
                    $('.sucure-checkout').show();
                }
            });
            $(document).on('click', '#cart-btn', function() {
                if ($('body').hasClass('payment')) {
                    $('body').removeClass('payment');
                    $('body').addClass('shipping');
                    $('#custom-opc-block-summary1').hide();
                    $('table.data.table.table-totals').hide();
                    $('.sucure-checkout').hide();
                }
            });
            if (!$('body').hasClass('catalog-category-view') && !$('body').hasClass('catalog-product-view')) {
                return;
            }

            function showFooterCartPopup() {
                let cart = cartData();
                let count = cart.summary_count || 0;
                let subtotal = cart.subtotal || 0;
                if (count < 1) {
                    return;
                }
                let bar = $('#footer-cart-bar');
                if (!bar.length) {
                    $('body').append(`
                        <div id="footer-cart-bar" class="footer-cart-bar show">
                            <div class="footer-cart-info">
                                <span class="footer-cart-items">${count} Items</span>
                                <span class="footer-cart-sep">|</span>
                                <span class="footer-cart-price">${subtotal.toLocaleString()}</span>
                            </div>
                            <a href="#" class="footer-cart-btn">View Cart</a>
                            <span class="close-footer-cart">&times;</span>
                        </div>
                    `);
                } else {
                    bar.find('.footer-cart-items').text(`${count} Items`);
                    bar.find('.footer-cart-price').html(subtotal.toLocaleString());
                    bar.addClass('show');
                }
            }
            $(document).on('ajax:addToCart', function() {
                customerData.reload(['cart'], true);
                let unsubscribe = cartData.subscribe(function(updatedCart) {
                    let newCount = updatedCart.summary_count || 0;
                    if (newCount > prevCount) {
                        showFooterCartPopup();
                    }
                    prevCount = newCount;
                    unsubscribe.dispose && unsubscribe.dispose();
                });
            });
            $(document).ajaxSuccess(function(event, xhr, settings) {
                var urlString = settings.url;
                var removeCartAjax = urlString.includes('/checkout/sidebar/removeItem');
                if (removeCartAjax) {
                    cartData.subscribe(function(updatedCart) {
                        var newCount = updatedCart.summary_count || 0;
                        showFooterCartPopup();
                        if (newCount == 0) {
                            $("#footer-cart-bar").removeClass("show");
                        }
                        prevCount = newCount;
                    });
                }
            });
            $(document).on('click', '.close-footer-cart', function() {
                $('#footer-cart-bar').removeClass('show');
            });
            $(document).on('click', '.footer-cart-btn', function(e) {
                e.preventDefault();
                $('#footer-cart-btn').addClass('cart-icon-div');
                var customer = customerData.get('customer')();
                if (!customer.firstname) {
                    $("#customer-account-link-id").trigger('click');
                } else if (customer.firstname) {
                    window.location.href = window.checkout.checkoutUrl + 'cart';
                }
                return false;
            });
        });
    };
});